// Shared study-method configuration and deterministic analysis helpers.
// No participant observations are generated by this module.
export const METHODS = {
  prototype: {label:'Prototype usability', description:'Instrumented GitHub Pages prototype, task timing, click paths and success signals'},
  ab_test: {label:'A/B implementation test', description:'Randomly assign one of two or more live designs and compare actual task performance'},
  card_sort: {label:'Card sorting', description:'Open, closed or hybrid information grouping'},
  tree_test: {label:'Tree testing', description:'Findability using a text-only navigation hierarchy'},
  first_click: {label:'First-click testing', description:'First interaction on a screenshot or mockup'},
  preference: {label:'Preference testing', description:'Compare two or more alternative designs'},
  survey: {label:'Survey', description:'Standalone, structured research questions'}
};
const SLUG=/^[a-z0-9-]{1,64}$/;
const nonempty=(v)=>typeof v==='string' && v.trim().length>0;
const isId=v=>SLUG.test(v||'');
const uniqueById=(items, kind)=>{
  if(!Array.isArray(items))throw new Error(`${kind} must be a list.`);
  const ids=new Set();
  for(const it of items){if(!isId(it.id)||ids.has(it.id))throw new Error(`${kind} IDs must be unique lowercase slugs.`);ids.add(it.id);if(!nonempty(it.label))throw new Error(`${kind} ${it.id} needs a label.`);}
  return ids;
};
export function secureURL(value, base='https://example.test/') {
  const url=new URL(value,base);
  if(!['https:','http:'].includes(url.protocol))throw new Error('URLs must use HTTPS or local HTTP.');
  if(url.protocol==='http:'&&!['127.0.0.1','localhost','[::1]'].includes(url.hostname))throw new Error('Public URLs must use HTTPS.');
  return url.href;
}
export function normalizeMethod(task){return task.method||'prototype';}
export function flattenTree(tree, prefix=[], out=[]){
  for(const node of tree||[]){const path=[...prefix,node.id];out.push({id:node.id,label:node.label,path,parent:prefix.at(-1)||null,leaf:!(node.children||[]).length});flattenTree(node.children||[],path,out);}return out;
}
export function validateQuestions(qs=[]){
  if(!Array.isArray(qs))throw new Error('Questions must be a list.');
  const ids=new Set();
  for(const q of qs){
    if(!isId(q.id)||ids.has(q.id))throw new Error('Question IDs must be unique lowercase slugs.');
    ids.add(q.id);
    if(!nonempty(q.text))throw new Error(`Question ${q.id} needs text.`);
    if(!['text','textarea','scale5','scale7','single','multi'].includes(q.type))throw new Error(`Unsupported question type for ${q.id}.`);
    if(['single','multi'].includes(q.type) && (!Array.isArray(q.options)||!q.options.length||q.options.some(x=>!nonempty(x))))throw new Error(`Question ${q.id} needs options.`);
  }
  return true;
}
export function validateActivity(task,base='https://example.test/'){
  if(!isId(task.id))throw new Error('Activity IDs must be lowercase slugs.');
  if(!nonempty(task.instructions))throw new Error(`Activity ${task.id} needs instructions.`);
  const method=normalizeMethod(task);
  if(!METHODS[method])throw new Error(`Unsupported method: ${method}.`);
  validateQuestions(task.questions||[]);
  if(method==='prototype'){
    // Uses activity URL when provided; otherwise the study-level URL in validateStudy.
    if(task.prototypeUrl)secureURL(task.prototypeUrl,base);
  }
  if(method==='ab_test'){
    if(!isId(task.experimentId||task.id))throw new Error('A/B experiment ID must be a lowercase slug.');
    if(!Array.isArray(task.variants)||task.variants.length<2)throw new Error('A/B tests need at least two implemented variants.');
    uniqueById(task.variants,'Variant');
    for(const v of task.variants){
      if(!nonempty(v.prototypeUrl))throw new Error(`Variant ${v.id} needs an interactive prototype URL.`);
      secureURL(v.prototypeUrl,base);
      if(v.revision!=null && (typeof v.revision!=='string'||v.revision.length>120))throw new Error(`Variant ${v.id} revision must be 120 characters or fewer.`);
    }
    if(task.successSignal && !isId(task.successSignal))throw new Error('A/B success signal must be a lowercase slug.');
  }
  if(method==='card_sort'){
    if(!['open','closed','hybrid'].includes(task.sortMode))throw new Error('Card sort mode must be open, closed, or hybrid.');
    if(!Array.isArray(task.cards)||task.cards.length<2)throw new Error('Card sorts need at least two cards.');
    uniqueById(task.cards,'Card');
    const cats=task.categories||[];uniqueById(cats,'Category');
    if(task.sortMode==='closed'&&cats.length<2)throw new Error('Closed card sorts need at least two predefined categories.');
  }
  if(method==='tree_test'){
    if(!Array.isArray(task.tree)||!task.tree.length)throw new Error('Tree tests need at least one root node.');
    const nodes=flattenTree(task.tree);
    const ids=new Set();
    for(const n of nodes){if(!isId(n.id)||ids.has(n.id)||!nonempty(n.label))throw new Error('Tree node IDs must be unique, labeled lowercase slugs.');ids.add(n.id);}
    if(!Array.isArray(task.correctNodeIds)||!task.correctNodeIds.length||task.correctNodeIds.some(x=>!ids.has(x)))throw new Error('Tree tests need at least one valid correct destination.');
  }
  if(method==='first_click'){
    if(!nonempty(task.imageUrl))throw new Error('First-click tests need an image URL.');
    secureURL(task.imageUrl,base);
    for(const area of task.targetAreas||[]){
      if(![area.x,area.y,area.width,area.height].every(n=>typeof n==='number'&&Number.isFinite(n)))throw new Error('First-click target values must be numeric percentages.');
      if(area.x<0||area.y<0||area.width<=0||area.height<=0||area.x+area.width>100.00001||area.y+area.height>100.00001)throw new Error('First-click target areas must be inside image bounds (0–100%).');
    }
  }
  if(method==='preference'){
    if(!Array.isArray(task.variants)||task.variants.length<2)throw new Error('Preference tests need at least two design options.');
    uniqueById(task.variants,'Variant');
    task.variants.forEach(v=>{if(!nonempty(v.imageUrl))throw new Error(`Variant ${v.id} needs an image.`);secureURL(v.imageUrl,base);});
  }
  if(method==='survey'&&!(task.questions||[]).length)throw new Error('Survey activities need at least one question.');
  return task;
}
export function pointInTarget(click,area){
  if(!click||!area)return false;
  return click.x_pct>=area.x && click.x_pct<=area.x+area.width && click.y_pct>=area.y && click.y_pct<=area.y+area.height;
}
export function scoreFirstClick(click,areas=[]){return areas.length? areas.some(area=>pointInTarget(click,area)) : null;}
export function scoreTree(tree,correctNodeIds=[],selectedNodeId,visitHistory=[]){
  const all=flattenTree(tree), lookup=new Map(all.map(n=>[n.id,n]));
  const success=selectedNodeId!=null && correctNodeIds.includes(selectedNodeId);
  const first=visitHistory.find(e=>e.action==='open');
  // A direct path makes no wrong turns and does not backtrack. Its opened nodes must
  // each be ancestors of the final correct destination (or the destination itself).
  const target=lookup.get(selectedNodeId), correctPath=target?.path||[];
  const visits=visitHistory.filter(e=>e.action==='open').map(e=>e.node_id);
  const backtracks=visitHistory.filter(e=>e.action==='back').length;
  const direct=success && backtracks===0 && visits.length>0 && visits.every((id,i)=>correctPath[i]===id) && visits.at(-1)===selectedNodeId;
  const acceptableRoots=correctNodeIds.map(id=>lookup.get(id)?.path?.[0]).filter(Boolean);
  const rootToTarget=!!first && acceptableRoots.includes(first.node_id);
  return {success,direct,first_selection:first?.node_id||null,first_branch_correct:rootToTarget,backtracks,selected_node:selectedNodeId||null,selected_path:target?.path||[],navigation_event_count:visitHistory.length,navigation_events:visitHistory.slice(0,120),history_truncated:visitHistory.length>120};
}
export function pairwiseSimilarity(sorts,cards){
  const list=cards.map(x=>typeof x==='string'?x:x.id);
  return list.map(a=>list.map(b=>{
    let matched=0,eligible=0;
    for(const sort of sorts){const groups=sort.groups||{};const ca=groups[a],cb=groups[b];if(ca && cb){eligible++;if(ca===cb)matched++;}}
    return {percent:eligible?Math.round(100*matched/eligible):null,n:eligible,paired:matched};
  }));
}
export function methodOutcomeRows(events){
  const versions=new Map((events||[]).filter(e=>e.kind==='session_started').map(e=>[e.session_id,e.payload?.study_version||null]));
  return (events||[]).filter(e=>e.kind==='task_ended').map(e=>({study_id:e.study_id,session_id:e.session_id,study_version:versions.get(e.session_id)||null,activity_id:e.task_id,method:e.payload?.method||'prototype',experiment_id:e.payload?.experiment_id||e.payload?.result?.experiment_id||null,variant_id:e.payload?.variant_id||e.payload?.result?.variant_id||null,variant_revision:e.payload?.variant_revision||e.payload?.result?.variant_revision||null,ended_at:e.created_at,time_seconds:e.payload?.time_seconds??null,result:e.payload?.result||{},self_report:e.payload?.self_report??null,observed_success:e.payload?.observed_success??null,interruptions:e.payload?.interruptions??0,interrupted_seconds:e.payload?.interrupted_seconds??0}));
}
export function exportMethodRows(rows){
  // CSV-friendly; preserves nested data as JSON for further coding or computation.
  return rows.map(r=>({...r,result:JSON.stringify(r.result)}));
}
export function randomizeVariants(variants,random=Math.random){
  const list=[...variants];
  for(let i=list.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}
  return list;
}

// Between-participant allocation. The UUID is generated after consent.
// Stable hashing keeps a participant on the same arm across tasks sharing experimentId.
// Equal-probability allocation is not quota balancing and provides no anti-repeat guarantee
// if a person opens a new session.
export function assignExperimentVariant(sessionId,studyId,task){
  if(!sessionId||!studyId||!task?.variants?.length)throw new Error('A/B assignment needs a session, study and variants.');
  const experimentId=task.experimentId||task.id;
  const variants=[...task.variants].sort((a,b)=>a.id.localeCompare(b.id));
  const key=`${sessionId}|${studyId}|${experimentId}`;
  let hash=2166136261;
  for(let i=0;i<key.length;i++){
    hash ^= key.charCodeAt(i);
    hash=Math.imul(hash,16777619);
  }
  const slot=Math.floor((hash>>>0)/4294967296*variants.length);
  return variants[slot];
}

// One row per exposure (task_started), including sessions without an end record.
// These records are joinable to answer/click exports by study_id, session_id, task_id.
export function experimentComparisonRows(events=[]){
  const sessions=new Map(events.filter(e=>e.kind==='session_started').map(e=>[e.session_id,e.payload?.study_version||null]));
  const externalIds=new Map(events.filter(e=>e.kind==='session_started').map(e=>[e.session_id,e.payload?.external_id||null]));
  const ends=new Map();
  for(const e of events){
    if(e.kind==='task_ended'&&e.payload?.method==='ab_test')ends.set(`${e.session_id}|${e.task_id}`,e);
  }
  return events.filter(e=>e.kind==='task_started'&&e.payload?.method==='ab_test').map(e=>{
    const end=ends.get(`${e.session_id}|${e.task_id}`), p=end?.payload||{}, r=p.result||{};
    return {study_id:e.study_id,study_version:sessions.get(e.session_id)||null,session_id:e.session_id,external_id:externalIds.get(e.session_id)||null,assignment:e.payload.assignment||null,
      experiment_id:e.payload.experiment_id||e.task_id,activity_id:e.task_id,
      variant_id:e.payload.variant_id||null,variant_revision:e.payload.variant_revision||null,
      assigned_at:e.created_at,ended_at:end?.created_at||null,status:end?'submitted':'not_submitted',
      time_seconds:end?(p.time_seconds??null):null,success_at_seconds:end?(p.success_at_seconds??null):null,click_count:end?(p.click_count??null):null,
      tracker_connected:end?(p.tracker_connected??false):null,
      success_signal_status:end?(r.success_signal_status||null):null,
      self_report:end?(p.self_report??null):null};
  });
}

// ---- v0.3.6: assignment and hand-off through the study link (e.g. from a Qualtrics randomizer) ----
// Link parameters:
//   variant=<variant-id>                 design for every A/B experiment that has this variant ID
//   variant.<experiment-id>=<variant-id> design for one experiment (wins over `variant`)
//   pid=<id>                             external participant/response ID, e.g. Qualtrics ${e://Field/ResponseID}
//   return=<https URL>                   where "Return to the survey" goes (allow-listed hosts only)
// Returns {experimentId: {variant_id, source}} with source 'link' | 'stable-hash-equal' |
// 'stable-hash-equal (link value not recognised)'.
export function resolveAssignments(study,sessionId,params){
  const get=k=>{const v=params?.get?.(k);return typeof v==='string'?v.trim():'';};
  const out={};
  for(const task of study?.tasks||[]){
    if(normalizeMethod(task)!=='ab_test'||!task.variants?.length)continue;
    const experimentId=task.experimentId||task.id;
    if(out[experimentId])continue;
    const wanted=get(`variant.${experimentId}`)||get('variant');
    const match=wanted&&task.variants.find(v=>v.id===wanted);
    if(match)out[experimentId]={variant_id:match.id,source:'link'};
    else out[experimentId]={variant_id:assignExperimentVariant(sessionId,study.id,task).id,source:wanted?'stable-hash-equal (link value not recognised)':'stable-hash-equal'};
  }
  return out;
}
export function variantForTask(task,assignments){
  const a=assignments?.[task.experimentId||task.id];
  return task.variants?.find(v=>v.id===a?.variant_id)||null;
}
export function cleanExternalId(value){
  const v=String(value||'').trim();
  return /^[A-Za-z0-9_.:-]{1,80}$/.test(v)?v:null;
}
// Only https links on allow-listed hosts (default: qualtrics.com and its subdomains) are used,
// so a study link cannot be turned into a redirect to an arbitrary site.
export function safeReturnUrl(value,hosts=['qualtrics.com']){
  if(!value)return null;
  let url;try{url=new URL(value);}catch{return null;}
  if(url.protocol!=='https:')return null;
  const host=url.hostname.toLowerCase();
  return hosts.some(h=>{h=String(h).toLowerCase().replace(/^\./,'');return host===h||host.endsWith(`.${h}`);})?url:null;
}
// Values Qualtrics can store as embedded data straight from the link (no custom JavaScript):
// rs_session, rs_pid (the pid the participant arrived with), rs_status, rs_variant (or rs_variant_<experiment> when several), and per A/B task in
// study order k = 1, 2…: rs_ab<k>_task, _variant, _success (received/not_observed/unavailable),
// _self (completed/unable), _time (seconds), _clicks. No personal data is included.
export function buildReturnUrl(base,{sessionId,status,assignments,abResults,tasks=[],externalId=null,device=null}){
  const url=new URL(base.href);
  url.searchParams.set('rs_session',sessionId);
  if(externalId)url.searchParams.set('rs_pid',externalId);
  if(device)url.searchParams.set('rs_device',device);
  url.searchParams.set('rs_status',status);
  const entries=Object.entries(assignments||{});
  if(entries.length===1)url.searchParams.set('rs_variant',entries[0][1].variant_id);
  else for(const [exp,a] of entries)url.searchParams.set(`rs_variant_${exp}`,a.variant_id);
  tasks.filter(t=>normalizeMethod(t)==='ab_test').forEach((t,i)=>{
    const r=abResults?.[t.id];if(!r)return;const k=`rs_ab${i+1}_`;
    url.searchParams.set(`${k}task`,t.id);
    url.searchParams.set(`${k}variant`,r.variant_id||'');
    url.searchParams.set(`${k}success`,r.success_signal_status||'');
    url.searchParams.set(`${k}self`,r.self_report||'');
    url.searchParams.set(`${k}time`,String(r.time_seconds??''));
    url.searchParams.set(`${k}clicks`,String(r.click_count??''));
    url.searchParams.set(`${k}tts`,String(r.success_at_seconds??''));
  });
  return url.href;
}
